import { describe, expect, it } from 'vitest'
import { createFetchClient, FetchFailure } from '../server/lib/fetch-client'

describe('createFetchClient', () => {
  it('refuses a call, before sending it, when the secret of the source is not set', async () => {
    const calls: string[] = []
    const { fetch } = globalThis
    globalThis.fetch = (async (value: unknown) => {
      calls.push(String(value))
      throw new Error('no network in this test')
    }) as typeof fetch
    try {
      const call = createFetchClient({ baseUrl: 'https://api.example.com/v1', headers: {}, unconfigured: true })
      await expect(call('/things', { method: 'GET' })).rejects.toMatchObject({ status: 0, notConfigured: true })
      expect(calls).toEqual([])
    } finally {
      globalThis.fetch = fetch
    }
  })

  it('sends the call when the secret is set: a failure of it is not "not configured"', async () => {
    const calls: string[] = []
    const { fetch } = globalThis
    globalThis.fetch = (async (value: unknown) => {
      calls.push(String(value))
      throw new Error('no network in this test')
    }) as typeof fetch
    try {
      const call = createFetchClient({ baseUrl: 'https://api.example.com/v1', headers: { authorization: 'Bearer secret' } })
      await expect(call('/things', { method: 'GET' })).rejects.toMatchObject({ notConfigured: false })
      expect(calls).toEqual(['https://api.example.com/v1/things'])
    } finally {
      globalThis.fetch = fetch
    }
  })

  it('refuses a "." or ".." segment, encoded or not, without calling the API', async () => {
    const calls: string[] = []
    const { fetch } = globalThis
    globalThis.fetch = (async (value: unknown) => {
      calls.push(String(value))
      throw new Error('no network in this test')
    }) as typeof fetch
    try {
      const call = createFetchClient({ baseUrl: 'https://api.example.com/v1', headers: {} })
      for (const segment of ['..', '.', '%2e%2e', '%2E.', '.%2e', '%2e']) {
        await expect(call(`/things/${segment}/parts`, { method: 'GET' })).rejects.toBeInstanceOf(FetchFailure)
      }
      expect(calls).toEqual([])
    } finally {
      globalThis.fetch = fetch
    }
  })
})
